const can = (userRole, action) => {
  try {
    const ov = JSON.parse(localStorage.getItem("bc_role_perms") || "null");
    if (ov && ov[action] !== undefined) return ov[action].includes(userRole);
  } catch(e) {}
  return (ROLE_PERMS[action] || []).includes(userRole);
};


/* ─── ANIMATED NUMBER COUNTER ────────────────────────────────── */
function AnimatedNumber({ value, duration = 900, prefix = "", suffix = "" }) {
  const [display, setDisplay] = useState(0);
  const frame = useRef(null);
  const numVal = parseFloat(String(value).replace(/[^0-9.]/g, "")) || 0;
  const isString = isNaN(Number(value));
  useEffect(() => {
    if (isString) { setDisplay(value); return; }
    let start = null;
    const animate = (ts) => {
      if (!start) start = ts;
      const progress = Math.min((ts - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setDisplay(Math.round(eased * numVal));
      if (progress < 1) frame.current = requestAnimationFrame(animate);
    };
    frame.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frame.current);
  }, [numVal, duration, isString, value]);
  if (isString) return <>{prefix}{value}{suffix}</>;
  return <>{prefix}{display.toLocaleString()}{suffix}</>;
}

