/* ─── SHARED HELPERS (module-level so all components can use) ── */
const iTag = (txt, clr) => {
  const c = clr || "#6366f1";
  return <span style={{display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:"8.5px",fontWeight:"900",letterSpacing:".12em",textTransform:"uppercase",fontFamily:"'Courier New',monospace",color:c,background:c+"1a",border:`1px solid ${c}30`,borderRadius:"5px",padding:"2px 6px",lineHeight:1.6,whiteSpace:"nowrap",flexShrink:0}}>{txt}</span>;
};

/* ─── TOAST / NOTIFICATION POPUP COMPONENT ─────────────────── */
const ToastContainer = ({ toasts }) => {
  if (!toasts.length) return null;
  const colors = {
    success: { bg: "#10b981", label: "DONE",  title: "Success"  },
    error:   { bg: "#ef4444", label: "FAIL",  title: "Alert"    },
    info:    { bg: "#3b82f6", label: "INFO",  title: "Notice"   },
    warning: { bg: "#f59e0b", label: "ATTN",  title: "Warning"  },
  };
  return (
    <div style={{ position: "fixed", top: "72px", right: "20px", zIndex: 9999, display: "flex", flexDirection: "column", gap: "10px", pointerEvents: "none", maxWidth: "340px", width: "100%" }}>
      {toasts.map(toast => {
        const c = colors[toast.type] || colors.info;
        return (
          <div key={toast.id} style={{
            display: "flex", alignItems: "flex-start", gap: "12px",
            padding: "14px 16px", borderRadius: "14px",
            background: "rgba(10,20,38,0.97)",
            border: `1px solid ${c.bg}35`,
            boxShadow: `0 12px 40px rgba(0,0,0,0.5), 0 0 0 1px ${c.bg}15`,
            pointerEvents: "all", backdropFilter: "blur(12px)",
            position: "relative", overflow: "hidden",
            animation: "slideInRight 0.35s cubic-bezier(0.34,1.4,0.64,1) both",
          }}>
            <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: "2px", background: `linear-gradient(90deg, ${c.bg}, ${c.bg}55)` }} />
            <div style={{ width: "3px", alignSelf: "stretch", borderRadius: "99px", background: c.bg, flexShrink: 0 }} />
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, marginTop: "1px" }}>
              {iTag(c.label, c.bg)}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: "10px", fontWeight: 700, color: c.bg, textTransform: "uppercase", letterSpacing: ".08em", marginBottom: "3px" }}>{c.title}</div>
              <div style={{ fontSize: "13px", fontWeight: 600, color: "#dde6f5", lineHeight: 1.4 }}>{toast.message}</div>
              {toast.sub && <div style={{ fontSize: "11px", color: "#5c7391", marginTop: "3px", lineHeight: 1.35 }}>{toast.sub}</div>}
            </div>
          </div>
        );
      })}
    </div>
  );
};

