  const [toasts, setToasts] = useState([]);
  // Apply appearance settings to :root CSS vars
  useEffect(() => {
    const root = document.documentElement;
    const fontMap  = { Small: "11px", Medium: "13px", Large: "16px" };
    const densityMap = { Compact: "4px", Default: "10px", Comfortable: "16px" };
    const pagePadMap = { Compact: "14px 18px", Default: "26px 30px", Comfortable: "38px 44px" };
    const animMap  = { None: "0ms", Reduced: "80ms", Normal: "200ms", Fast: "350ms" };
    root.style.setProperty("--bc-font-size",    fontMap[appFontSize]     || "13px");
    root.style.setProperty("--bc-density",      densityMap[layoutDensity] || "10px");
    root.style.setProperty("--bc-page-padding", pagePadMap[layoutDensity] || "26px 30px");
    root.style.setProperty("--bc-anim-speed",   animMap[appAnimSpeed]    || "200ms");
    root.style.setProperty("--bc-accent",       accentColor);
    root.style.setProperty("--bc-accent-dim",   accentColor + "20");
    // Scale font on main layout (affects elements without explicit font-size)
    document.documentElement.style.setProperty("font-size", fontMap[appFontSize] || "13px");
    // Data attrs for CSS overrides
    document.documentElement.setAttribute("data-fontsize", appFontSize || "Medium");
    document.documentElement.setAttribute("data-density",  layoutDensity || "Default");
    document.documentElement.setAttribute("data-anim",     appAnimSpeed || "Normal");
  }, [accentColor, appFontSize, layoutDensity, appAnimSpeed, settingsRev]);

  // Preserve settings scroll — restore only on section change, save on scroll
  useEffect(() => {
    const el = settingsScrollRef.current;
    if (!el) return;
    el.scrollTop = settingsSavedY.current;
    const onScroll = () => { settingsSavedY.current = el.scrollTop; };
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => el.removeEventListener("scroll", onScroll);
  }, [settingsSection]);

  const addToast = (message, type = "success", sub = "") => {
    const id = Date.now() + Math.random();
    setToasts(prev => [...prev, { id, message, type, sub }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3500);
    // Check quiet hours
    const _isQuiet = (() => { try { const now = new Date(); const hm = now.getHours() * 60 + now.getMinutes(); const qs = (localStorage.getItem("bc_quiet_start") || "22:00").split(":"); const qe = (localStorage.getItem("bc_quiet_end") || "07:00").split(":"); const qsm = parseInt(qs[0])*60+parseInt(qs[1]); const qem = parseInt(qe[0])*60+parseInt(qe[1]); return qsm > qem ? (hm >= qsm || hm < qem) : (hm >= qsm && hm < qem); } catch(e) { return false; } })();
    // Sound alert
    if (!_isQuiet && localStorage.getItem("bc_notif_sound") !== "false") {
      try {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = ctx.createOscillator(); const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.type = "sine";
        osc.frequency.value = type === "error" ? 200 : type === "info" ? 440 : 523;
        gain.gain.setValueAtTime(0.1, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
        osc.start(); osc.stop(ctx.currentTime + 0.3);
      } catch(e) {}
    }
    // Desktop notification (only when tab is in background and not quiet hours)
    if (!_isQuiet && localStorage.getItem("bc_notif_desktop") !== "false" && typeof Notification !== "undefined" && Notification.permission === "granted" && document.hidden) {
      try { new Notification(appCompany, { body: message + (sub ? " — " + sub : ""), silent: true }); } catch(e) {}
    }
  };

