  const saveRecurring = (taskId, interval) => {
    if (!interval || interval === "none") return;
    const upd = { ...recurringTasks, [taskId]: interval };
    setRecurringTasks(upd);
    localStorage.setItem("bc_recurring", JSON.stringify(upd));
  };
  const getNextDueDate = (fromDate, interval) => {
    const d = fromDate ? new Date(fromDate) : new Date();
    if (interval === "daily")   d.setDate(d.getDate() + 1);
    if (interval === "weekly")  d.setDate(d.getDate() + 7);
    if (interval === "monthly") d.setMonth(d.getMonth() + 1);
    return d.toISOString().slice(0, 10);
  };

  const createTask = async (projectId) => {
    if (!taskInput.trim()) return;
    try {
      await axios.post("http://localhost:5000/api/tasks", {
        project_id: projectId,
        title: taskInput.trim(),
        priority: taskPriority || "medium",
        due_date: taskDueDate || null,
        assigned_to: taskAssignTo || null,
      }, { headers: headers() });
      const taskName = taskInput.trim();
      const recInterval = taskRecurring;
      const _defPrio = localStorage.getItem("bc_def_priority")?.toLowerCase() || "medium";
      const _defDays = localStorage.getItem("bc_def_duedays") || "7";
      const _autoDate = _defDays !== "None" ? (() => { const _d = new Date(); _d.setDate(_d.getDate() + parseInt(_defDays)); return _d.toISOString().slice(0,10); })() : "";
      setTaskInput(""); setTaskPriority(_defPrio); setTaskDueDate(_autoDate); setTaskAssignTo(""); setTaskRecurring("none");
      await fetchTasks(projectId);
      if (recInterval && recInterval !== "none") {
        const allTasks = await axios.get(`http://localhost:5000/api/tasks?project_id=${projectId}`, { headers: headers() });
        const newest = (allTasks.data || []).find(tt => tt.title === taskName);
        if (newest) saveRecurring(newest.id, recInterval);
      }
      addToast("Task added!", "success", taskName);
      if (taskAssignTo && String(taskAssignTo) !== String(user?.id)) {
        const assigneeName = users.find(u2 => String(u2.id) === String(taskAssignTo))?.name || "teammate";
        addToast(`Task assigned to ${assigneeName}`, "info", taskName);
      }
      logActivity("added task", "task", taskName, projectId, selectedProject?.title);
    } catch (e) { addToast("Failed to add task", "error"); console.log(e); }
  };

  const saveDeps = (newDeps) => { setTaskDeps(newDeps); localStorage.setItem("bc_task_deps", JSON.stringify(newDeps)); };
  const isTaskBlocked = (taskId, projectId) => {
    const blockedBy = taskDeps[taskId] || [];
    if (!blockedBy.length) return false;
    const allTasks = Object.values(tasks).flat();
    return blockedBy.some(depId => { const dep = allTasks.find(t2 => String(t2.id) === String(depId)); return dep && !dep.completed; });
  };

  const toggleTask = async (taskId, projectId) => {
    // Check if blocked before completing
    const allT = (tasks[projectId] || []);
    const task = allT.find(t2 => t2.id === taskId);
    if (task && !task.completed && isTaskBlocked(taskId, projectId)) {
      const blockedBy = taskDeps[taskId] || [];
      const allTasks = Object.values(tasks).flat();
      const pendingDeps = blockedBy.filter(depId => { const dep = allTasks.find(t2 => String(t2.id) === String(depId)); return dep && !dep.completed; });
      const names = pendingDeps.map(id => allTasks.find(t2 => String(t2.id) === String(id))?.title || "unknown").join(", ");
      addToast(`Blocked by: ${names}`, "error");
      return;
    }
    try {
      const res = await axios.put(`http://localhost:5000/api/tasks/${taskId}/toggle`, {}, { headers: headers() });
      const interval = recurringTasks[taskId];
      if (interval && interval !== "none" && res.data?.completed) {
        const origList = (tasks[projectId] || []);
        const orig = origList.find(t2 => t2.id === taskId);
        if (orig) {
          const nr = await axios.post("http://localhost:5000/api/tasks", {
            project_id: projectId,
            title: orig.title,
            priority: orig.priority,
            due_date: getNextDueDate(orig.due_date, interval),
            assigned_to: orig.assigned_to || null,
          }, { headers: headers() });
          if (nr.data?.id) saveRecurring(nr.data.id, interval);
          addToast("Recurring task created!", "success", orig.title);
        }
      }
      fetchTasks(projectId);
      addToast("Task updated!", "info");
    } catch (e) { console.log(e); }
  };

