  const fetchWeather = async (locationStr) => {
    if (!locationStr) return;
    setWeatherLoading(true);
    try {
      const city = locationStr.split(",")[0].trim();
      // wttr.in — completely free, no API key needed
      const r = await axios.get(`https://wttr.in/${encodeURIComponent(city)}?format=j1`);
      const cur = r.data.current_condition?.[0];
      const area = r.data.nearest_area?.[0];
      if (!cur) { setWeather(null); setWeatherLoading(false); return; }
      const code = parseInt(cur.weatherCode);
      const icon = code === 113 ? "☀️" : [116, 119].includes(code) ? "⛅" : [122, 143, 248, 260].includes(code) ? "🌫️" : code >= 176 && code <= 282 ? "🌧️" : code >= 290 && code <= 395 ? "❄️" : "🌦️";
      const desc = cur.weatherDesc?.[0]?.value || "Clear";
      const cityName = area?.areaName?.[0]?.value || city;
      setWeather({
        temp: Math.round(cur.temp_C),
        feels: Math.round(cur.FeelsLikeC),
        rain: cur.precipMM,
        wind: Math.round(cur.windspeedKmph),
        humidity: cur.humidity,
        icon, desc, city: cityName,
      });
    } catch (e) { console.log("Weather error:", e.message); setWeather(null); }
    setWeatherLoading(false);
  };

