  /* ── Voice Messages ── */
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioChunksRef.current = [];
      const mr = new MediaRecorder(stream, { mimeType: "audio/webm" });
      mr.ondataavailable = e => { if (e.data.size > 0) audioChunksRef.current.push(e.data); };
      mr.onstop = async () => {
        stream.getTracks().forEach(t2 => t2.stop());
        const blob = new Blob(audioChunksRef.current, { type: "audio/webm" });
        const file = new File([blob], `voice_${Date.now()}.webm`, { type: "audio/webm" });
        try {
          const fd = new FormData(); fd.append("file", file);
          const r = await axios.post("http://localhost:5000/api/messages/upload", fd, { headers: { ...headers(), "Content-Type": "multipart/form-data" } });
          const msgR = await axios.post("http://localhost:5000/api/messages", { receiver_id: selectedChat.id, content: `[aud:${r.data.filename}]` }, { headers: headers() });
          setChatMessages(prev => [...prev, msgR.data]);
        } catch(e2) { addToast("Voice send failed","error"); }
      };
      mediaRecorderRef.current = mr; mr.start();
      setIsRecording(true); setRecordingTime(0);
      recordTimerRef.current = setInterval(() => setRecordingTime(t2 => t2 + 1), 1000);
    } catch(e) { addToast("Mic access denied","error"); }
  };
  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) { mediaRecorderRef.current.stop(); }
    setIsRecording(false); clearInterval(recordTimerRef.current);
  };

