  const smartDate = (ts) => {
    if (!ts) return "—";
    const d = new Date(ts);
    const now = new Date();
    const diffMs = now - d;
    const diffDays = Math.floor(diffMs / 86400000);
    if (diffDays === 0) return "Today";
    if (diffDays === 1) return "Yesterday";
    if (diffDays === -1) return "Tomorrow";
    if (diffDays > 1 && diffDays < 7) return `${diffDays}d ago`;
    if (diffDays < 0 && diffDays > -7) return `In ${Math.abs(diffDays)}d`;
    return d.toLocaleDateString("en-IN", { day: "numeric", month: "short", year: d.getFullYear() !== now.getFullYear() ? "numeric" : undefined });
  };

  const fmtDateTime = (ts) => {
    if (!ts) return "";
    const d = new Date(ts);
    const tz = appTimezone || "Asia/Kolkata";
    // Date part
    let datePart;
    const fmt = appDateFmt || "DD/MM/YYYY";
    if (fmt === "DD/MM/YYYY")   datePart = d.toLocaleDateString("en-GB",  { day:"2-digit", month:"2-digit", year:"numeric", timeZone: tz }).replace(/\//g,"/");
    else if (fmt === "MM/DD/YYYY") datePart = d.toLocaleDateString("en-US", { day:"2-digit", month:"2-digit", year:"numeric", timeZone: tz });
    else if (fmt === "YYYY-MM-DD") datePart = d.toLocaleDateString("sv-SE", { timeZone: tz });
    else if (fmt === "D MMM YYYY") datePart = d.toLocaleDateString("en-GB", { day:"numeric", month:"short", year:"numeric", timeZone: tz });
    else                           datePart = d.toLocaleDateString("en-GB", { day:"numeric", month:"long",  year:"numeric", timeZone: tz });
    // Time part
    const use24 = (appTimeFmt || "12h") === "24h";
    const timePart = d.toLocaleTimeString("en-GB", { hour:"2-digit", minute:"2-digit", hour12: !use24, timeZone: tz });
    return datePart + " · " + timePart;
  };

  const fmtDate = (ts) => {
    if (!ts) return "";
    const d = new Date(ts);
    const tz = appTimezone || "Asia/Kolkata";
    const fmt = appDateFmt || "DD/MM/YYYY";
    if (fmt === "DD/MM/YYYY")   return d.toLocaleDateString("en-GB",  { day:"2-digit", month:"2-digit", year:"numeric", timeZone: tz });
    if (fmt === "MM/DD/YYYY")   return d.toLocaleDateString("en-US",  { day:"2-digit", month:"2-digit", year:"numeric", timeZone: tz });
    if (fmt === "YYYY-MM-DD")   return d.toLocaleDateString("sv-SE",  { timeZone: tz });
    if (fmt === "D MMM YYYY")   return d.toLocaleDateString("en-GB",  { day:"numeric", month:"short",  year:"numeric", timeZone: tz });
    return d.toLocaleDateString("en-GB", { day:"numeric", month:"long", year:"numeric", timeZone: tz });
  };

  // Currency-aware budget formatter — converts from INR using live exchange rates
  const currSym = CURRENCY_SYMBOLS[appCurrency] || "₹";
  const fmt$ = (n) => {
    if (!n && n !== 0) return "—";
    const num = Number(n);
    if (appCurrency === "INR" || !exchangeRates[appCurrency]) {
      return fmtBudgetWithSym(num, "₹");
    }
    const converted = num * (exchangeRates[appCurrency] || 1);
    return fmtBudgetWithSym(converted, currSym);
  };

